// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(0));
        // transfer ownership so the stored owner is known
        vm.prank(c.owner());
        c.transferOwnership(newOwner);
        address storedOwner = c.owner();
        // make a call to owner() from a different caller
        vm.prank(caller);
        address returnedOwner = c.owner();
        // the call must return the stored owner, not the caller
        assertTrue(returnedOwner == storedOwner);
    }
}

