pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(actor != address(0));
        vm.prank(actor);
        c.transferOwnership(newOwner);
        address storedOwner = newOwner;
        ProxyCaller proxy = new ProxyCaller(c);
        address returnedOwner = proxy.callOwner();
        assertTrue(returnedOwner == storedOwner);
    }
}

contract ProxyCaller {
    C c;
    constructor(C _c) { c = _c; }
    function callOwner() external view returns (address) {
        return c.owner();
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address actor) public {
        // actor will be the owner, and we call from a contract to make tx.origin != msg.sender
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0); // actor is an EOA
        // Transfer ownership to actor
        c.transferOwnership(actor);
        // Deploy a helper that calls C.owner() and exposes the result
        Caller helper = new Caller();
        // Prank actor so tx.origin is actor, but record return via helper
        vm.prank(actor);
        address returned = helper.callOwner(address(c));
        // Reference: owner is actor (stored). Mutant: returns tx.origin (also actor, since call started from EOA).
        // To expose difference, we need tx.origin != stored owner. That happens when helper initiates.
        // But since we pranked actor, helper.callOwner executes with msg.sender=helper, tx.origin=actor.
        // Stored owner = actor. Reference returns actor, mutant returns tx.origin = actor.
        // They still match. To make them differ, we need stored owner != tx.origin.
        // So we set owner to something else, but call from actor via helper.
        // Let's set owner to address(this) (test contract), and call from actor via helper.
        // Reference returns address(this), mutant returns tx.origin = actor.
        c.transferOwnership(address(this));
        vm.prank(actor);
        address ret = helper.callOwner(address(c));
        assertTrue(ret == address(this)); // reference returns stored owner; mutant returns tx.origin (actor)
    }
}

contract Caller {
    function callOwner(address target) external view returns (address) {
        return C(target).owner();
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address actor) public {
        // 1. restrict to safe calls
        vm.assume(actor != address(0));
        // 2. deploy a helper that forwards owner()
        Forwarder fwd = new Forwarder();
        vm.prank(actor);
        c.transferOwnership(actor);
        // 3. the true owner is the address we transferred to
        address expectedOwner = actor;
        // call owner() through the forwarder; this makes msg.sender != tx.origin
        vm.prank(address(0xdead));
        address returned = fwd.getOwner(address(c));
        // 4. assertion: the returned owner must be the expected owner for every caller
        assertTrue(returned == expectedOwner);
    }
}

contract Forwarder {
    function getOwner(address target) external view returns (address) {
        return C(target).owner();
    }
}
